Given the head of a singly linked list and an integer k, return the data of the node present at the k-th position using 1-based indexing. Return -1 if the k-th node does not exist.Examples:Input: k = 3,head of a Linked ListOutput: 3Explanation: The node value at index 3 is 3.Input: k = 6,Output: -1Explanation: The linked list contains fewer than 6 nodes, so no node exists at index 6.Try It YourselfTable of Content[Naive Approach] Store Node Values - O(n) Time and O(n) Space[Expected Approach] Iterative Traversal - O(k) Time and O(1) Space[Naive Approach] Store Node Values - O(n) Time and O(n) SpaceThe idea is - Traverse the linked list and store the value of every node in an array. Since the list uses 1-based indexing while the array uses 0-based indexing, the required node value will be stored at index k - 1. If k is greater than the number of nodes, return -1.
            C++

    #include <iostream>
#include <vector>
using namespace std;

struct Node {
    int data;
    Node* next;

    Node(int x) {
        data = x;
        next = nullptr;
    }
};

int getNode(Node* head, int k) {
    vector<int> values;

    // Store the data of every node.
    while (head != nullptr) {
        values.push_back(head->data);
        head = head->next;
    }

    if (k > 0 && k <= static_cast<int>(values.size())) {
        return values[k - 1];
    }

    return -1;
}

int main() {
    Node* head1 = new Node(1);
    head1->next = new Node(2);
    head1->next->next = new Node(3);
    head1->next->next->next = new Node(4);
    head1->next->next->next->next = new Node(5);
    head1->next->next->next->next->next = new Node(6);
    head1->next->next->next->next->next->next = new Node(7);

    cout << getNode(head1, 3) << "\n";

    Node* head2 = new Node(19);
    head2->next = new Node(28);
    head2->next->next = new Node(37);
    head2->next->next->next = new Node(48);
    head2->next->next->next->next = new Node(55);

    cout << getNode(head2, 6) << "\n";

    return 0;
}


